package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;
import java.util.*;
final class MajorIncidentsBrowserAcceptance {
 static void click(Page page,String label){page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName(label).setExact(true)).press("Enter");}
 static void review(Page page){page.getByLabel("Probable cause").fill("Database failover stalled");page.getByLabel("Lessons learned").fill("Exercise database failover");page.getByLabel("Follow-up actions").fill("Coordinate a recovery drill");click(page,"Save post-incident review");}
 static void run(BrowserTest h)throws Exception{
  String id,child;try(var db=h.store.open()){PlatformFoundationTest.bind(db);for(String user:List.of("MajorBrowserProposer","MajorBrowserCommander"))Service.createAccount(db,map("name",user,"role","agent","password",WorkflowSupport.PASSWORD));id=Service.create(db,"incident",map("short_description","Checkout major outage"),"admin").get("sys_id").toString();child=Service.create(db,"incident",map("short_description","Checkout affected store <script>"),"admin").get("sys_id").toString();db.connection.commit();}
  try(var p=Playwright.create();var browser=p.chromium().launch();var context=browser.newContext();var staffContext=browser.newContext();var commanderContext=browser.newContext()){
   var staff=staffContext.newPage();h.login(staff,"MajorBrowserProposer");staff.navigate(h.base()+"/record/incident/"+id);staff.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Major incident workbench")).press("Enter");staff.getByLabel("Proposal reason").fill("Multiple stores cannot check out");staff.getByLabel("Business impact").fill("Checkout unavailable");click(staff,"Propose major incident");assertThat(staff.locator("main")).containsText("candidate");assertThat(staff.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Declare major incident"))).hasCount(0);
   var admin=context.newPage();h.login(admin,"admin");admin.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Major incidents").setExact(true)).press("Enter");admin.getByLabel("Major process status").selectOption("candidate");click(admin,"Filter incidents");ReleaseBrowserAcceptance.accessible(admin);admin.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Checkout major outage · candidate")).press("Enter");admin.getByLabel("Incident commander",new Page.GetByLabelOptions().setExact(true)).selectOption("MajorBrowserCommander");admin.getByLabel("Acceptance reason").fill("Confirmed major outage");click(admin,"Declare major incident");assertThat(admin.locator("main")).containsText("declared");
   var commander=commanderContext.newPage();h.login(commander,"MajorBrowserCommander");commander.navigate(h.base()+"/record/incident/"+id+"/major");commander.getByLabel("Status update").fill("Database failover underway <script>");click(commander,"Publish staff update");commander.getByLabel("Related incident summary").fill("Checkout affected store");click(commander,"Search incidents");click(commander,"Link incident: Checkout affected store <script>");assertThat(commander.locator("main script")).hasCount(0);assertThat(commander.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Unlink incident: Checkout affected store <script>"))).hasCount(1);staff.navigate(h.base()+"/record/incident/"+child+"/major");assertThat(staff.locator("main")).containsText("Database failover underway <script>");ReleaseBrowserAcceptance.accessible(staff);
   for(String theme:List.of("light","dark")){if(theme.equals("dark")){click(commander,"Dark mode");commander.setViewportSize(390,844);}ReleaseBrowserAcceptance.accessible(commander);commander.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/major-incident-"+theme+".png")).setFullPage(true));}
   commander.getByLabel("Restoration outcome").fill("Healthy database now serving checkout");click(commander,"Record service restoration");review(commander);commander.getByLabel("Reopen reason").fill("A store still affected");click(commander,"Reopen incident response");commander.getByLabel("Restoration outcome").fill("All stores recovered");click(commander,"Record service restoration");review(commander);
   admin.reload();admin.getByLabel("New commander").selectOption("MajorBrowserCommander");admin.getByLabel("Handoff reason").fill("Confirm command after response review");click(admin,"Assign incident commander");commander.reload();review(commander);staff.navigate(h.base()+"/record/incident/"+child);for(String state:List.of("2","6")){staff.getByLabel("State").selectOption(state);click(staff,"Save changes →");}commander.reload();commander.getByLabel("Closure reason").fill("Related incident resolved and review complete");click(commander,"Close major incident");assertThat(commander.getByRole(AriaRole.HEADING,new Page.GetByRoleOptions().setName("Completed review"))).isVisible();assertThat(commander.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Unlink incident: Checkout affected store <script>"))).hasCount(0);ReleaseBrowserAcceptance.accessible(commander);commander.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/major-incident-closed-dark.png")).setFullPage(true));
   admin.reload();click(admin,"Unlink incident: Checkout affected store <script>");assertThat(admin.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Unlink incident: Checkout affected store <script>"))).hasCount(0);admin.navigate(h.base()+"/major-incidents?status=closed");assertThat(admin.locator("main")).containsText("Checkout major outage · closed");
  }
 }
}
